using System;
using System.IO;
using System.Text;
using System.Linq;
using System.Collections.Generic;
using System.Xml.Serialization;
using System.Web.Script.Serialization;
using System.IO.Compression;
using System.Security;

namespace JingFamily {
 public class Person {
  public string Id=Guid.NewGuid().ToString("N"), Name="", Gender="未知", Birth="", Death="", Place="", Address="", Phone="", Occupation="", Generation="", Biography="", FatherId="", MotherId="", Portrait="";
  public List<string> Spouses=new List<string>();
  public override string ToString(){return Name;}
 }
 public class FamilyEvent { public string Id=Guid.NewGuid().ToString("N"),Date="",Title="",Place="",PersonId="",Notes=""; }
 public class Document { public string Id=Guid.NewGuid().ToString("N"),Title="",PersonId="",File="",Notes=""; }
 public class ResearchTask { public string Id=Guid.NewGuid().ToString("N"),Title="",PersonId="",Due="",Notes=""; public bool Done=false; }
 public class FamilyData {
  public int Version=2;
  public string Title="我的家谱", Motto="慎终追远 · 记录家族的每一段故事", History="";
  public List<Person> People=new List<Person>();
  public List<FamilyEvent> Events=new List<FamilyEvent>();
  public List<Document> Documents=new List<Document>();
  public List<ResearchTask> Tasks=new List<ResearchTask>();
 }
 public static class Store {
  public static string Root=Path.Combine(Environment.GetFolderPath(Environment.SpecialFolder.LocalApplicationData),"JingFamily");
  public static string FilePath {get{return Path.Combine(Root,"family.xml");}}
  public static FamilyData Data=new FamilyData();
  public static string X(string s){return SecurityElement.Escape(s??"")??"";}
  public static byte[] Serialize(FamilyData d){using(var m=new MemoryStream()){new XmlSerializer(typeof(FamilyData)).Serialize(m,d);return m.ToArray();}}
  public static FamilyData Deserialize(byte[] b){using(var m=new MemoryStream(b)){var settings=new System.Xml.XmlReaderSettings();settings.DtdProcessing=System.Xml.DtdProcessing.Prohibit;settings.XmlResolver=null;using(var r=System.Xml.XmlReader.Create(m,settings)){return (FamilyData)new XmlSerializer(typeof(FamilyData)).Deserialize(r);}}}
  public static void Load(){Directory.CreateDirectory(Root);Directory.CreateDirectory(Path.Combine(Root,"media"));if(System.IO.File.Exists(FilePath)){Data=Deserialize(System.IO.File.ReadAllBytes(FilePath));Validate(Data);}}
  public static void Save(){Validate(Data);Directory.CreateDirectory(Root);string temp=FilePath+".tmp";System.IO.File.WriteAllBytes(temp,Serialize(Data));if(System.IO.File.Exists(FilePath))System.IO.File.Replace(temp,FilePath,FilePath+".previous");else System.IO.File.Move(temp,FilePath);}
  public static Person Get(string id){return Data.People.Find(p=>p.Id==id);}
  public static void Commit(FamilyData d){Validate(d);var old=Data;Data=d;try{Save();}catch{Data=old;throw;}}
  public static string Name(string id){var p=Get(id);return p==null?"—":p.Name;}
  public static bool IsAncestor(FamilyData d,string ancestor,string child){var seen=new HashSet<string>();var todo=new Stack<string>();todo.Push(child);while(todo.Count>0){string id=todo.Pop();if(!seen.Add(id))continue;var p=d.People.Find(x=>x.Id==id);if(p==null)continue;foreach(string next in new[]{p.FatherId,p.MotherId}){if(next==ancestor)return true;if(!String.IsNullOrEmpty(next))todo.Push(next);}}return false;}
  public static void Validate(FamilyData d){
   if(d==null||d.People==null||d.Events==null||d.Documents==null)throw new Exception("家谱数据不完整。");
   if(d.Version!=1&&d.Version!=2)throw new Exception("不支持此数据版本。");d.Version=2;
   if(d.People.Count>20000)throw new Exception("单份家谱最多支持 20,000 位成员。");
   var ids=new HashSet<string>();foreach(var p in d.People){if(p==null||String.IsNullOrWhiteSpace(p.Id)||!ids.Add(p.Id))throw new Exception("成员编号为空或重复。");if(String.IsNullOrWhiteSpace(p.Name))throw new Exception("成员姓名不能为空。");if(p.Spouses==null)throw new Exception("配偶关系数据不完整。");CheckMedia(p.Portrait);CheckDate(p.Birth);CheckDate(p.Death);if(p.Birth.Length>0&&p.Death.Length>0&&DateStart(p.Birth)>DateEnd(p.Death))throw new Exception(p.Name+"的去世日期早于出生日期。");}
   foreach(var p in d.People){foreach(string id in new[]{p.FatherId,p.MotherId}.Concat(p.Spouses)){if(String.IsNullOrEmpty(id))continue;if(id==p.Id||!ids.Contains(id))throw new Exception(p.Name+"的亲属关系无效。");}if(p.FatherId!=""&&p.FatherId==p.MotherId)throw new Exception("父亲和母亲不能是同一人。");if(IsAncestor(d,p.Id,p.Id))throw new Exception("亲子关系形成循环，请检查。");foreach(var s in p.Spouses){if(s==p.FatherId||s==p.MotherId||IsAncestor(d,s,p.Id)||IsAncestor(d,p.Id,s))throw new Exception("配偶不能是直系亲属。");var q=d.People.Find(x=>x.Id==s);if(!q.Spouses.Contains(p.Id))throw new Exception("配偶关系必须双向一致。");}}
   foreach(var e in d.Events){CheckDate(e.Date);if(String.IsNullOrWhiteSpace(e.Title))throw new Exception("事件标题不能为空。");if(!String.IsNullOrEmpty(e.PersonId)&&!ids.Contains(e.PersonId))throw new Exception("事件关联成员不存在。");}
   foreach(var doc in d.Documents){CheckMedia(doc.File);if(!String.IsNullOrEmpty(doc.PersonId)&&!ids.Contains(doc.PersonId))throw new Exception("资料关联成员不存在。");}
   if(d.Tasks==null)d.Tasks=new List<ResearchTask>();var taskIds=new HashSet<string>();foreach(var t in d.Tasks){if(t==null||String.IsNullOrWhiteSpace(t.Title)||!taskIds.Add(t.Id))throw new Exception("待办标题为空或编号重复。");CheckDate(t.Due);if(t.Due!=""&&t.Due.Length!=10)throw new Exception("待办截止日请填 YYYY-MM-DD。");if(t.PersonId!=""&&!ids.Contains(t.PersonId))throw new Exception("待办关联成员不存在。");}
  }
  public static DateTime DateStart(string s){return DateTime.ParseExact(s,s.Length==4?"yyyy":s.Length==7?"yyyy-MM":"yyyy-MM-dd",System.Globalization.CultureInfo.InvariantCulture);}
  public static DateTime DateEnd(string s){var d=DateStart(s);return s.Length==4?new DateTime(d.Year,12,31):s.Length==7?new DateTime(d.Year,d.Month,DateTime.DaysInMonth(d.Year,d.Month)):d;}
  public static void CheckDate(string s){if(String.IsNullOrEmpty(s))return;DateTime dt;string[] formats={"yyyy","yyyy-MM","yyyy-MM-dd"};if(!DateTime.TryParseExact(s,formats,System.Globalization.CultureInfo.InvariantCulture,System.Globalization.DateTimeStyles.None,out dt))throw new Exception("日期请填写 YYYY、YYYY-MM 或 YYYY-MM-DD，也可以留空。");}
  public static void CheckMedia(string s){if(String.IsNullOrEmpty(s))return;if(Path.IsPathRooted(s)||!s.StartsWith("media/",StringComparison.Ordinal)||s.Contains("..")||s.Contains("\\")||s.Contains(":"))throw new Exception("附件路径无效。");}
  public static string AddMedia(string source){if(new FileInfo(source).Length>100L*1024*1024)throw new Exception("单个附件上限为 100 MB。");string dest="media/"+Guid.NewGuid().ToString("N")+Path.GetExtension(source);Directory.CreateDirectory(Path.Combine(Root,"media"));System.IO.File.Copy(source,Path.Combine(Root,dest));return dest;}
  public static void DeletePerson(string id){Data.People.RemoveAll(p=>p.Id==id);foreach(var p in Data.People){if(p.FatherId==id)p.FatherId="";if(p.MotherId==id)p.MotherId="";p.Spouses.Remove(id);}foreach(var e in Data.Events)if(e.PersonId==id)e.PersonId="";foreach(var d in Data.Documents)if(d.PersonId==id)d.PersonId="";foreach(var t in Data.Tasks)if(t.PersonId==id)t.PersonId="";Save();}
  public static void Backup(string path){BackupAt(path,Data,Root);}
  public static void BackupAt(string path,FamilyData data,string root){Validate(data);string tmp=path+"."+Guid.NewGuid().ToString("N")+".tmp";try{WriteBackup(tmp,data,root);if(System.IO.File.Exists(path))System.IO.File.Replace(tmp,path,null);else System.IO.File.Move(tmp,path);}finally{if(System.IO.File.Exists(tmp))System.IO.File.Delete(tmp);}}
  static void WriteBackup(string path,FamilyData data,string root){using(var z=ZipFile.Open(path,ZipArchiveMode.Create)){var entry=z.CreateEntry("family.xml");using(var s=entry.Open()){byte[] b=Serialize(data);s.Write(b,0,b.Length);}var files=data.People.Select(p=>p.Portrait).Concat(data.Documents.Select(d=>d.File)).Where(f=>!String.IsNullOrEmpty(f)).Distinct();long total=0;foreach(var f in files){CheckMedia(f);string full=Path.Combine(root,f);if(!System.IO.File.Exists(full))throw new Exception("附件丢失："+f);total+=new FileInfo(full).Length;if(total>512L*1024*1024)throw new Exception("完整备份附件总量上限为 512 MB。");z.CreateEntryFromFile(full,f);}}}
  public static FamilyData ReadBackup(string path,out Dictionary<string,byte[]> files){files=new Dictionary<string,byte[]>();FamilyData d;using(var z=ZipFile.OpenRead(path)){var entry=z.GetEntry("family.xml");if(entry==null||entry.Length>50*1024*1024)throw new Exception("备份无效或数据过大。");using(var m=new MemoryStream()){using(var s=entry.Open())s.CopyTo(m);d=Deserialize(m.ToArray());}Validate(d);long total=0;foreach(var e in z.Entries){if(e.FullName=="family.xml")continue;CheckMedia(e.FullName);total+=e.Length;if(total>512L*1024*1024)throw new Exception("备份附件总计不能超过 512 MB。");using(var m=new MemoryStream()){using(var s=e.Open())s.CopyTo(m);files.Add(e.FullName,m.ToArray());}}}foreach(string f in d.People.Select(p=>p.Portrait).Concat(d.Documents.Select(x=>x.File)).Where(x=>!String.IsNullOrEmpty(x))){if(!files.ContainsKey(f))throw new Exception("备份缺少附件："+f);}return d;}
  public static void Replace(FamilyData d,Dictionary<string,byte[]> media){Validate(d);if(Data.People.Count>0||Data.Events.Count>0||Data.Documents.Count>0||Data.Tasks.Count>0){string dir=Path.Combine(Root,"backups");Directory.CreateDirectory(dir);Backup(Path.Combine(dir,"before-restore-"+DateTime.Now.ToString("yyyyMMdd-HHmmss-fff")+".zip"));}if(media!=null)foreach(var pair in media){CheckMedia(pair.Key);Directory.CreateDirectory(Path.Combine(Root,"media"));System.IO.File.WriteAllBytes(Path.Combine(Root,pair.Key),pair.Value);}Commit(d);}
  public static string Csv(string s){return "\""+(s??"").Replace("\"","\"\"")+"\"";}
  public static void ExportCsv(string path){var b=new StringBuilder("姓名,性别,出生日期,去世日期,籍贯,住址,电话,职业,字辈,父亲,母亲,配偶,生平\r\n");foreach(var p in Data.People)b.AppendLine(String.Join(",",new[]{p.Name,p.Gender,p.Birth,p.Death,p.Place,p.Address,p.Phone,p.Occupation,p.Generation,Name(p.FatherId),Name(p.MotherId),String.Join("、",p.Spouses.Select(Name)),p.Biography}.Select(s=>Csv(s.Length>0&&"=+-@".Contains(s[0])?"'"+s:s))));System.IO.File.WriteAllText(path,b.ToString(),new UTF8Encoding(true));}
  public static void ExportJson(string path){System.IO.File.WriteAllText(path,new JavaScriptSerializer{MaxJsonLength=50*1024*1024}.Serialize(Data),new UTF8Encoding(false));}
  public static string GedDate(string s){if(s.Length==10)return DateTime.ParseExact(s,"yyyy-MM-dd",null).ToString("dd MMM yyyy",System.Globalization.CultureInfo.InvariantCulture).ToUpperInvariant();if(s.Length==7)return DateTime.ParseExact(s,"yyyy-MM",null).ToString("MMM yyyy",System.Globalization.CultureInfo.InvariantCulture).ToUpperInvariant();return s;}
  public static string ReadGedDate(string s){DateTime dt;foreach(string fmt in new[]{"d MMM yyyy","dd MMM yyyy","MMM yyyy","yyyy","yyyy-MM-dd"})if(DateTime.TryParseExact(s,fmt,System.Globalization.CultureInfo.InvariantCulture,System.Globalization.DateTimeStyles.None,out dt))return dt.ToString(fmt=="yyyy"?"yyyy":fmt=="MMM yyyy"?"yyyy-MM":"yyyy-MM-dd");return "";}
  public static void ExportGed(string path){var b=new StringBuilder("0 HEAD\r\n1 SOUR JingFamily\r\n1 GEDC\r\n2 VERS 5.5.1\r\n2 FORM LINEAGE-LINKED\r\n1 CHAR UTF-8\r\n");var fams=new List<Tuple<string,string,List<string>>>();foreach(var p in Data.People.Where(x=>x.FatherId!=""||x.MotherId!="")){var f=fams.Find(x=>x.Item1==p.FatherId&&x.Item2==p.MotherId);if(f==null){f=Tuple.Create(p.FatherId,p.MotherId,new List<string>());fams.Add(f);}f.Item3.Add(p.Id);}foreach(var p in Data.People)foreach(string s in p.Spouses)if(!fams.Any(f=>(f.Item1==p.Id&&f.Item2==s)||(f.Item2==p.Id&&f.Item1==s)))fams.Add(Tuple.Create(p.Id,s,new List<string>()));foreach(var p in Data.People){b.AppendLine("0 @I"+p.Id+"@ INDI");b.AppendLine("1 NAME "+p.Name.Replace("\r"," ").Replace("\n"," "));b.AppendLine("1 SEX "+(p.Gender=="男"?"M":p.Gender=="女"?"F":"U"));if(p.Birth!=""){b.AppendLine("1 BIRT");b.AppendLine("2 DATE "+GedDate(p.Birth));}if(p.Death!=""){b.AppendLine("1 DEAT");b.AppendLine("2 DATE "+GedDate(p.Death));}if(p.Place!="")b.AppendLine("1 _ORIGIN "+p.Place.Replace("\n"," ").Replace("\r"," "));if(p.Biography!=""){var lines=p.Biography.Replace("\r","").Split('\n');b.AppendLine("1 NOTE "+lines[0]);foreach(var line in lines.Skip(1))b.AppendLine("2 CONT "+line);}for(int i=0;i<fams.Count;i++){var f=fams[i];if(f.Item1==p.Id||f.Item2==p.Id)b.AppendLine("1 FAMS @F"+i+"@");if(f.Item3.Contains(p.Id))b.AppendLine("1 FAMC @F"+i+"@");}}for(int i=0;i<fams.Count;i++){var f=fams[i];b.AppendLine("0 @F"+i+"@ FAM");if(f.Item1!="")b.AppendLine("1 HUSB @I"+f.Item1+"@");if(f.Item2!="")b.AppendLine("1 WIFE @I"+f.Item2+"@");foreach(string c in f.Item3)b.AppendLine("1 CHIL @I"+c+"@");}b.AppendLine("0 TRLR");System.IO.File.WriteAllText(path,b.ToString(),new UTF8Encoding(false));}
  public static FamilyData ImportGed(string path){var d=new FamilyData();d.Title=Path.GetFileNameWithoutExtension(path);var map=new Dictionary<string,Person>();var families=new List<List<string>>();Person p=null;List<string> fam=null;string context="";foreach(string raw in System.IO.File.ReadLines(path,Encoding.UTF8)){var parts=raw.Trim().Split(new[]{' '},3);if(parts.Length<2)continue;string level=parts[0],tag=parts[1],val=parts.Length>2?parts[2]:"";if(level=="0"){p=null;fam=null;context="";if(val=="INDI"){p=new Person();map.Add(tag,p);d.People.Add(p);}else if(val=="FAM"){fam=new List<string>();families.Add(fam);}continue;}if(p!=null){if(level=="1"){context=tag;if(tag=="NAME")p.Name=val.Replace("/","").Trim();if(tag=="SEX")p.Gender=val=="M"?"男":val=="F"?"女":"未知";if(tag=="NOTE")p.Biography=val;if(tag=="_ORIGIN")p.Place=val;}else if(tag=="DATE"){if(context=="BIRT")p.Birth=ReadGedDate(val);if(context=="DEAT")p.Death=ReadGedDate(val);}else if(tag=="CONT"&&context=="NOTE")p.Biography+="\r\n"+val;}if(fam!=null&&level=="1"&&(tag=="HUSB"||tag=="WIFE"||tag=="CHIL"))fam.Add(tag+" "+val);}foreach(var f in families){string father="",mother="";foreach(string s in f){var kv=s.Split(' ');if(!map.ContainsKey(kv[1]))continue;if(kv[0]=="HUSB")father=map[kv[1]].Id;if(kv[0]=="WIFE")mother=map[kv[1]].Id;}if(father!=""&&mother!=""){map.Values.First(x=>x.Id==father).Spouses.Add(mother);map.Values.First(x=>x.Id==mother).Spouses.Add(father);}foreach(string s in f.Where(x=>x.StartsWith("CHIL "))){string key=s.Substring(5);if(map.ContainsKey(key)){map[key].FatherId=father;map[key].MotherId=mother;}}}foreach(var x in d.People)x.Spouses=x.Spouses.Distinct().ToList();Validate(d);return d;}
  public static FamilyData Sample(){var d=new FamilyData{Title="景·谱 · 示例",Motto="树高千尺有根，水流万里有源",History="这是一份虚构的三代家谱，供体验软件使用。\r\n请在「家谱管理」中新建独立家谱，开始记录自己的家族。"};var a=new Person{Name="景明远",Gender="男",Birth="1938-03-12",Death="2018-10-08",Place="江苏苏州",Occupation="教师",Generation="明",Biography="热爱诗书，重视家风传承。此为虚构示例。"};var b=new Person{Name="林淑华",Gender="女",Birth="1941-06-18",Place="浙江杭州"};a.Spouses.Add(b.Id);b.Spouses.Add(a.Id);var c=new Person{Name="景文成",Gender="男",Birth="1965-09-03",FatherId=a.Id,MotherId=b.Id,Generation="文",Occupation="工程师",Place="江苏苏州"};var e=new Person{Name="景文宁",Gender="女",Birth="1969-02-15",FatherId=a.Id,MotherId=b.Id,Generation="文"};var f=new Person{Name="陈雅琴",Gender="女",Birth="1967-11-20",Occupation="医生"};c.Spouses.Add(f.Id);f.Spouses.Add(c.Id);var g=new Person{Name="景知行",Gender="男",Birth="1994-08-26",FatherId=c.Id,MotherId=f.Id,Generation="知"};var h=new Person{Name="景知夏",Gender="女",Birth="1998-04-06",FatherId=c.Id,MotherId=f.Id,Generation="知"};d.People.AddRange(new[]{a,b,c,f,e,g,h});d.Events.Add(new FamilyEvent{Date="1965-09-03",Title="文成出生",Place="苏州",PersonId=c.Id,Notes="虚构示例事件"});d.Events.Add(new FamilyEvent{Date="1990-10-01",Title="家族团聚",Place="苏州",Notes="三代同堂，共叙家事（虚构示例）。"});return d;}
 }
}
